update public.mechanics set hint = 'Discard to draw, including landcycling and typecycling' where id = 'cycling';
update public.mechanics set hint = 'Double-faced cards, convert, or More Than Meets the Eye' where id = 'transform';
update public.mechanics set hint = 'Crew and living metal' where id = 'vehicles';
update public.mechanics set hint = 'Background enchantments, or choose a background' where id = 'backgrounds';
